package app.repositories

import app.Sql
import app.common.Page
import app.entities.AuditLog
import java.sql.Connection
import java.sql.ResultSet

/** Keeps audit_log rows in the database, with SQL through JDBC. A write joins the transaction already open, or is committed at once. */
open class SqlAuditLogRepository(private val held: Connection?) {
    private val connection get() = checkNotNull(held) { "This repository has no connection" }

    /** The columns every read selects. */
    private val columns = "\"at\", \"message\""

    /** At most limit rows from offset, by primary key, and how many there are. */
    open fun list(offset: Int, limit: Int): Page<AuditLog> {
        val items = Sql.all(connection, "SELECT " + columns + " FROM \"audit_log\" ORDER BY \"at\", \"message\" LIMIT ? OFFSET ?", limit, offset) { toEntity(it) }
        val total = Sql.one(connection, "SELECT COUNT(*) FROM \"audit_log\"") { it.getLong(1) } ?: 0L
        return Page(items, total, offset, limit)
    }

    private fun toEntity(row: ResultSet): AuditLog = fill(row, AuditLog())

    /** Reads a row selected with the columns into entity. */
    private fun fill(row: ResultSet, entity: AuditLog): AuditLog {
        entity.at = row.getString(1)?.let { Sql.offsetDateTime(it) }
        entity.message = row.getString(2)
        return entity
    }
}

