    @BeforeTest
    fun open() {
        uow = MemoryUnitOfWork()
    }

    @Test
    fun createsAValidRow() {
        val service = CategoryService(uow)
        val row = Factories.newCategory(1)
        val created = service.createCategory(row)
        val found = service.findCategory(created.id!!)
        assertEquals(created.id, found.id)
    }

    @Test
    fun refusesAMissingValue() {
        val service = CategoryService(uow)
        val row = Factories.newCategory(1)
        row.name = null
        val error = assertFailsWith<ValidationFailedException> { service.createCategory(row) }
        assertEquals(listOf("name"), error.errors.map { it.field })
    }

    @Test
    fun refusesARepeatedUniqueValue() {
        val service = CategoryService(uow)
        val row = Factories.newCategory(1)
        val first = service.createCategory(row)
        val again = Factories.newCategory(2)
        again.name = first.name
        assertFailsWith<ConflictException> { service.createCategory(again) }
    }

    @Test
    fun keepsItsOwnUniqueValue() {
        val service = CategoryService(uow)
        val row = Factories.newCategory(1)
        val created = service.createCategory(row)
        val updated = service.updateCategory(created.id!!, CategoryChanges(name = Patch.of(created.name!!)))
        assertEquals(created.name, updated.name)
    }

    @Test
    fun saysWhenARowIsMissing() {
        val service = CategoryService(uow)
        assertFailsWith<NotFoundException> { service.findCategory(999999L) }
    }

    @Test
    fun deletesARow() {
        val service = CategoryService(uow)
        val row = Factories.newCategory(1)
        val created = service.createCategory(row)
        service.deleteCategory(created.id!!)
        assertFailsWith<NotFoundException> { service.findCategory(created.id!!) }
    }
}

